/// <summary>
/// CB411_412_ChargeThrough Post pending vendor invoice
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
void submitVendorInvoiceWorkflow(VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    if (_vendInvoiceInfoTable && _vendInvoiceInfoTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_vendInvoiceInfoTable, strFmt("@MET:CTAutoSubmitWorkflowComment", _vendInvoiceInfoTable.METCBCTNumber));
    }
}

    /// <summary>
    /// CB411_412_ChargeThrough Copy pending vendor invoice line charges to sales order line charges.
    /// </summary>    
    /// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
    /// <param name = "_salesLine">Sales order line</param>
    /// <param name = "_salestable">Sales table buffer</param>
    void copyChargesFromPendingVendorInvoice(VendInvoiceInfoTable _vendInvoiceInfoTable, SalesLine _salesLine = null, SalesTable _salestable = null)
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        MarkupTrans       markUpTransVendInvoiceInfoLine, markUpTransVendInvoiceInfoTable, markUpTransSalesLine, markupTransSalesTable;
        LineNum           markUpTransSalesLineLineNum, markUpTransSalesTableLineNum;
        RecordInsertList  markUpTransSalesLineRecordInsertList = new RecordInsertList(tableNum(MarkupTrans));
               
        
        if (metVendParameters.DefaultARChargeCode1 || metVendParameters.DefaultARChargeCode2 ||  metVendParameters.DefaultARChargeCode1ForCrossDock || metVendParameters.DefaultARChargeCode2)
        {   
            if (!markupCodeDisc1Txt || !markupCodeDisc2Txt)
            {
                markupCodeDisc1Txt = (_salestable.METInvoiceType == METInvoiceTypeSO::CrossDock && metVendParameters.DefaultARChargeCode1ForCrossDock) ?  MarkupTable::find(MarkupModuleType::Cust, metVendParameters.DefaultARChargeCode1ForCrossDock).Txt : MarkupTable::find(MarkupModuleType::Cust, metVendParameters.DefaultARChargeCode1).Txt;
                markupCodeDisc2Txt = (_salestable.METInvoiceType == METInvoiceTypeSO::CrossDock && metVendParameters.DefaultARChargeCode2ForCrossDock) ?  MarkupTable::find(MarkupModuleType::Cust, metVendParameters.DefaultARChargeCode2ForCrossDock).Txt : MarkupTable::find(MarkupModuleType::Cust, metVendParameters.DefaultARChargeCode2).Txt;
            }

            if (_salestable)
            {
                markUpTransSalesTableLineNum = MarkupTrans::lastLineNum(_salestable.TableId, _salestable.RecId);

                VendInvoiceInfoSubTable VendInvoiceInfoSubTable = VendInvoiceInfoSubTable::find(_vendInvoiceInfoTable.ParmId, _vendInvoiceInfoTable.TableRefId, '');

                while select markUpTransVendInvoiceInfoTable
                    where markUpTransVendInvoiceInfoTable.TransTableId == VendInvoiceInfoSubTable.TableId
                    && markUpTransVendInvoiceInfoTable.TransRecId == VendInvoiceInfoSubTable.RecId
                    && (markUpTransVendInvoiceInfoTable.LineNum == 1 || markUpTransVendInvoiceInfoTable.LineNum == 2)
                {
                    markUpTransSalesTableLineNum++;                    
                    markupTransSalesTable.clear();
                    markupTransSalesTable.data(markUpTransVendInvoiceInfoTable);
                    markupTransSalesTable.TransTableId   = _salestable.TableId;
                    markupTransSalesTable.TransRecId     = _salestable.RecId;
                    markupTransSalesTable.LineNum        = markUpTransSalesTableLineNum;
                    markupTransSalesTable.Value          = markUpTransVendInvoiceInfoTable.Value;
                    
                    markupTransSalesTable.SourceDocumentLine = 0;
                    if (markUpTransVendInvoiceInfoTable.LineNum == 1)
                    {
                        markupTransSalesTable.MarkupCode =  _salestable.METInvoiceType == METInvoiceTypeSO::CrossDock ?  metVendParameters.DefaultARChargeCode1ForCrossDock : metVendParameters.DefaultARChargeCode1;
                        markupTransSalesTable.Txt = markupCodeDisc1Txt;
                    }
                    else
                    {
                        markupTransSalesTable.MarkupCode = _salestable.METInvoiceType == METInvoiceTypeSO::CrossDock ?  metVendParameters.DefaultARChargeCode2ForCrossDock : metVendParameters.DefaultARChargeCode2;;
                        markupTransSalesTable.Txt = markupCodeDisc2Txt;
                    }
                    markUpTransSalesLineRecordInsertList.add(markupTransSalesTable);
                }
            }
            else
            {
                select firstonly vendInvoiceInfoLine
                    where vendInvoiceInfoLine.ParmId     == _vendInvoiceInfoTable.ParmId
                        && vendInvoiceInfoLine.TableRefId == _vendInvoiceInfoTable.TableRefId
                        // Bug_282653 - match line with same item, amount and item tax group
                        && vendInvoiceInfoLine.ItemId == _salesLine.ItemId
                        && vendInvoiceInfoLine.LineAmount == _salesLine.LineAmount
                        && vendInvoiceInfoLine.TaxItemGroup == _salesLine.TaxItemGroup;
                        // Bug_282653 - match line with same item, amount and item tax group
                
                if (vendInvoiceInfoLine)
                {
                    markUpTransSalesLineLineNum = MarkupTrans::lastLineNum(_salesLine.TableId, _salesLine.RecId);
                    _salestable = SalesTable::find(_salesLine.SalesId);
                    while select markUpTransVendInvoiceInfoLine
                    where markUpTransVendInvoiceInfoLine.TransTableId == vendInvoiceInfoLine.TableId
                        && markUpTransVendInvoiceInfoLine.TransRecId == vendInvoiceInfoLine.RecId
                        && (markUpTransVendInvoiceInfoLine.LineNum == 1 || markUpTransVendInvoiceInfoLine.LineNum == 2)
                    {
                        markUpTransSalesLineLineNum++;                        
                        markUpTransSalesLine.clear();
                        markUpTransSalesLine.data(markUpTransVendInvoiceInfoLine);
                        markUpTransSalesLine.TransTableId   = _salesLine.TableId;
                        markUpTransSalesLine.TransRecId     = _salesLine.RecId;
                        markUpTransSalesLine.LineNum        = markUpTransSalesLineLineNum;
                        markUpTransSalesLine.Value          = markUpTransVendInvoiceInfoLine.Value;
                        markUpTransSalesLine.ModuleType = MarkupModuleType::Cust;

                        markUpTransSalesLine.SourceDocumentLine = 0; // to avoid issue when posting SO invoice "The source document or source document line could not be updated."

                        if (markUpTransVendInvoiceInfoLine.LineNum == 1)
                        {
                            markUpTransSalesLine.MarkupCode = _salestable.METInvoiceType == METInvoiceTypeSO::CrossDock ?  metVendParameters.DefaultARChargeCode1ForCrossDock :  metVendParameters.DefaultARChargeCode1;
                            markUpTransSalesLine.Txt = markupCodeDisc1Txt;
                        }
                        else
                        {
                            markUpTransSalesLine.MarkupCode = _salestable.METInvoiceType == METInvoiceTypeSO::CrossDock ?  metVendParameters.DefaultARChargeCode2ForCrossDock : metVendParameters.DefaultARChargeCode2;
                            markUpTransSalesLine.Txt = markupCodeDisc2Txt;
                        }

                        markUpTransSalesLineRecordInsertList.add(markUpTransSalesLine);
                    }
                }
            }
                            
        }
        
        markUpTransSalesLineRecordInsertList.insertDatabase();
    }

    /// <summary>
    /// Count number of charge through to be processed
    /// </summary>
    /// <param name = "_query"><c>Query</c> object</param>
    /// <returns>Number of charge through to be processed</returns>
    protected int countChargeThrough(Query _query)
    {
        QueryBuildDataSource qbds = _query.dataSourceTable(tablenum(METCBCTInvoiceHeaderTable));
        qbds.addSelectionField(fieldNum(METCBCTInvoiceHeaderTable, RecId), SelectionField::Count);

        QueryRun qr = new QueryRun(_query);

        return SysQuery::countTotal(qr);
    }

