    /// <summary>
    /// Creates Vendor invoice Journal
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable">Charge through header table</param>
    /// <returns>LedgerJournalTable</returns>
    public LedgerJournalTable createVendInvoiceJournal(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {        
        LedgerJournalTrans vendInvJourTrans;
        LedgerJournalTable vendInvJourTable;
        Voucher voucher;              
        METCBCTInvoiceLine vendLine;
        RecordInsertList vendInvoiceJourLineList;
        
        VendTable               vendTable = VendTable::find(_cbCTInvoiceHeaderTable.VendorAccount);
        
        try
        {
            // create journal header
            vendInvJourTable.clear();
            vendInvJourTable.initValue();
            vendInvJourTable.initFromLedgerJournalName(VendParameters::find().METLedgerJournalNameIdVendInvoice);
            
            vendInvJourTable.CurrencyCode = vendTable.Currency;
            vendInvJourTable.modifiedField(fieldNum(LedgerJournalTable, CurrencyCode));
            vendInvJourTable.DefaultDimension = _cbCTInvoiceHeaderTable.FinancialDimension;
            vendInvJourTable.JournalNum = JournalTableData::newTable(vendInvJourTable).nextJournalId();
            vendInvJourTable.insert();
        
            vendInvoiceJourLineList = new RecordInsertList(tableNum(LedgerJournalTrans));
           
            // create vendor line
            this.createJournalLine(_cbCTInvoiceHeaderTable, vendInvJourTrans,
                vendInvJourTable.JournalNum,
                voucher,
                LedgerJournalACType::Vend,
                LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(vendTable.AccountNum, LedgerJournalACType::Vend),
                _cbCTInvoiceHeaderTable.Reference,
                0,
                METCBCTInvoiceLine::totalVendAmount(_cbCTInvoiceHeaderTable.Number),
                _cbCTInvoiceHeaderTable.FinancialDimension);

            vendInvoiceJourLineList.add(vendInvJourTrans);

            voucher = vendInvJourTrans.Voucher;

            RefRecId mainAccountId, ledgerDimension;
            DimensionHierarchyId accountStructureId;

            // create ledger lines
            while select vendLine
                where vendLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number
                && vendLine.VendCustType == METCBCTVendCust::Vend
            {
                mainAccountId = LedgerDimensionFacade::getMainAccountFromLedgerDimension(vendLine.LedgerDimension).RecId;

                accountStructureId = DimensionHierarchy::getAccountStructure(mainAccountId);

                ledgerDimension = LedgerDimensionDefaultingEngine:: getLedgerDimensionFromAccountAndDim(mainAccountId, accountStructureId, vendLine.FinancialDimension);
                
                this.createJournalLine(_cbCTInvoiceHeaderTable, vendInvJourTrans,
                    vendInvJourTable.JournalNum,
                    voucher,
                    LedgerJournalACType::Ledger, 
                    ledgerDimension,
                    vendLine.Description,
                    vendLine.Amount,
                    0,
                    vendLine.FinancialDimension,
                    vendLine.TaxGroup,
                    vendLine.TaxItemGroup);
          
                vendInvoiceJourLineList.add(vendInvJourTrans);
            }

            // Insert VendInvoiceJourLines in DB;
            vendInvoiceJourLineList.insertDatabase();
           
            // Attach note
            this.createAttachedNote(vendInvJourTable.RecId,
                vendInvJourTable.TableId,
                strFmtLB(strFmt("@MET:FTICustomerNotes", _cbCTInvoiceHeaderTable.Number, _cbCTInvoiceHeaderTable.VendorAccount,
                                vendTable.name())),
                vendInvJourTable.DataAreaId);

        }
        catch
        {
            error(this.getInfologMessage());
            throw error("@MET:VendorInvoiceJournalError");
        }

        return vendInvJourTable;
    }

    /// <summary>
    /// Create Vend Invoice Journal line
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable">Charge through invoice header table</param>
    /// <param name = "_journalLine">Journa Line</param>
    /// <param name = "_journalNum">Journal batch number</param>
    /// <param name = "_voucher">voucher info</param>
    /// <param name = "_type">Ledger journal account type</param>
    /// <param name = "_ledgerDimension">Ledger dimension</param>
    /// <param name = "_txt">Description</param>
    /// <param name = "_creditAmount">Credit amount</param>
    /// <param name = "_debitAmount">Debit Amount</param>
    /// <param name = "_defaultDimension">Default Dimension</param>
    /// <param name = "_taxGroup">Tax group </param>
    /// <param name = "_itemTaxGroup"> item sales tax group</param>
    private void createJournalLine(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable,
                                    LedgerJournalTrans _journalLine,
                                    LedgerJournalId _journalNum,
                                    Voucher         _voucher,
                                    LedgerJournalACType _type,
                                    DimensionDynamicAccount _ledgerDimension,
                                    LedgerJournalTransTxt _txt,
                                    AmountCurCredit _creditAmount,
                                    AmountCurDebit  _debitAmount,
                                    LedgerDimensionValueSet _defaultDimension,
                                    TaxGroupJournal _taxGroup = '',
                                    TaxGroupJournal _itemTaxGroup = '')
    {
        LedgerJournalEngine engine = new LedgerJournalEngine();

        _journalLine.clear();
        _journalLine.initValue();
      
        if ( System.String::IsNullOrEmpty(_voucher) )
        {
            engine.ledgerJournalTable(LedgerJournalTable::find(_journalNum));
            engine.initValue(_journalLine);
        }
        else
        {
            _journalLine.JournalNum = _journalNum;
            _journalLine.Voucher = _voucher;
        }

        if ( _cbCTInvoiceHeaderTable.TransactionDate != _journalLine.TransDate )
        {
            _journalLine.TransDate = _cbCTInvoiceHeaderTable.TransactionDate;
            _journalLine.modifiedField(fieldNum(LedgerJournalTrans, TransDate));
        }

        if ( _type != _journalLine.AccountType )
        {
            _journalLine.AccountType = _type;
            _journalLine.modifiedField(fieldNum(LedgerJournalTrans, AccountType));
        }
        _journalLine.DocumentNum = _journalNum;
        _journalLine.LedgerDimension = _ledgerDimension;
        _journalLine.modifiedField(fieldNum(LedgerJournalTrans, LedgerDimension));
        engine.accountModified(_journalLine);
        _journalLine.DocumentDate = _cbCTInvoiceHeaderTable.DocumentDate;
        _journalLine.Invoice = _cbCTInvoiceHeaderTable.TaxInvoiceNum;
        _journalLine.modifiedField(fieldNum(LedgerJournalTrans, Invoice));
        _journalLine.Txt = _txt;
        _journalLine.AmountCurCredit = _creditAmount;
        _journalLine.modifiedField(fieldNum(LedgerJournalTrans, AmountCurCredit));
        _journalLine.AmountCurDebit = _debitAmount;
        _journalLine.modifiedField(fieldNum(LedgerJournalTrans, AmountCurDebit));
        _journalLine.DefaultDimension = _defaultDimension;
        _journalLine.Approver = HcmWorkerLookup::currentWorker();
        _journalLine.Approved = NoYes::Yes;
        _journalLine.Due = _cbCTInvoiceHeaderTable.VendDueDate;

        if ( _cbCTInvoiceHeaderTable.CurrencyCode != _journalLine.CurrencyCode)
        {
            _journalLine.CurrencyCode = _cbCTInvoiceHeaderTable.CurrencyCode;
            _journalLine.modifiedField(fieldNum(LedgerJournalTrans, CurrencyCode));
        }

        if ( _taxGroup && _taxGroup != _journalLine.TaxGroup )
        {
            _journalLine.TaxGroup = _taxGroup;
            _journalLine.modifiedField(fieldNum(LedgerJournalTrans, TaxGroup));
        }

        if ( _itemTaxGroup && _itemTaxGroup != _journalLine.TaxItemGroup )
        {
            _journalLine.TaxItemGroup = _itemTaxGroup;
            _journalLine.modifiedField(fieldNum(LedgerJournalTrans, TaxItemGroup));
        }

        _journalLine.METALMSupplierVolumetricRebateNumber = _cbCTInvoiceHeaderTable.Number;

    }

