    /// <summary>
    /// Creates Customer free text invoice
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable">Charge through header table</param>
    /// <returns>CustInvoiceTable</returns>
    public CustInvoiceTable createCustFreeTextInvoice(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        CustInvoiceTable    custInvoiceTable;
        CustInvoiceLine     custInvoiceLine;
        CustTable           custTable = CustTable::find(_cbCTInvoiceHeaderTable.CustomerAccount);
        RecordInsertList    custInvoiceLineList;
        METCBCTInvoiceLine  custLine;

        boolean isSVR = _cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::SVR;

        try
        {
            changecompany(_cbCTInvoiceHeaderTable.DataAreaId)
            {   
                //create header
                custInvoiceTable.clear();
                custInvoiceTable.initValue();
                custInvoiceTable.OrderAccount = _cbCTInvoiceHeaderTable.CustomerAccount;
                custInvoiceTable.InvoiceId = NumberSeq::newGetNum(CustParameters::numRefCustInvoiceId()).num();
                custInvoiceTable.modifiedField(fieldNum(CustInvoiceTable, OrderAccount));
                custInvoiceTable.DocumentDate = _cbCTInvoiceHeaderTable.DocumentDate;
                custInvoiceTable.InvoiceDate = _cbCTInvoiceHeaderTable.TransactionDate;
                custInvoiceTable.modifiedField(fieldNum(CustInvoiceTable, InvoiceDate));
                custInvoiceTable.CurrencyCode = _cbCTInvoiceHeaderTable.CurrencyCode;
                custInvoiceTable.Payment = _cbCTInvoiceHeaderTable.CustPaymTermId;                
                custInvoiceTable.DefaultDimension = _cbCTInvoiceHeaderTable.FinancialDimension;
                custInvoiceTable.CustomerRef = strFmt("@MET:PlaceHolder", _cbCTInvoiceHeaderTable.VendorAccount, _cbCTInvoiceHeaderTable.TaxInvoiceNum);
                custInvoiceTable.PurchOrderFormNum = _cbCTInvoiceHeaderTable.Number;
                custInvoiceTable.DueDate = _cbCTInvoiceHeaderTable.CustDueDate;
                
                if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::SVR)
                {
                    custInvoiceTable.CustomerInvoiceOriginId = VendParameters::find().METSVRInvoiceOrigin;
                }
                else if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::RDA)
                {
                    custInvoiceTable.CustomerInvoiceOriginId = VendParameters::find().METRDAInvoiceOrigin;
                }
               
                custInvoiceTable.insert();

                custInvoiceLineList = new RecordInsertList(tableNum(CustInvoiceLine));
            }
            LineNum  linenum = 0;
            // create lines
            while select custLine
                where custLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number
                && custLine.VendCustType == METCBCTVendCust::Cust
            {
                linenum++;
                changecompany(_cbCTInvoiceHeaderTable.DataAreaId)
                {
                    int factor = isSVR && custLine.Amount > 0 ? -1 : 1;

                    custInvoiceLine.clear();
                    custInvoiceLine.initValue();
                    custInvoiceLine.LineNum = linenum;
                    custInvoiceLine.ParentRecId = custInvoiceTable.RecId;
                    custInvoiceLine.initFromCustInvoiceTable(custInvoiceTable);
                    custInvoiceLine.Description = custLine.Description;
                    custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, Description));
                    custInvoiceLine.LedgerDimension = custLine.LedgerDimension;
                    custInvoiceLine.DefaultDimension = custLine.FinancialDimension;
                    custInvoiceLine.TaxGroup = custLine.TaxGroup;
                    custInvoiceLine.TaxItemGroup = custLine.TaxItemGroup;                    
                    custInvoiceLine.Quantity = factor;
                    custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, Quantity));

                    // Bug 278583: CB411 - Chargeback/ chargethrough SVR Transaction posting validation
                    custInvoiceLine.UnitPrice = factor * custLine.Amount;
                    if(isSVR)
                    {
                        custInvoiceLine.AmountCur = factor * (abs(custInvoiceLine.Quantity) * abs(custLine.Amount));
                    }
                    else
                    {
                        custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, UnitPrice));
                    }
                    
                    custInvoiceLineList.add(custInvoiceLine);
                }
            }
            changecompany(_cbCTInvoiceHeaderTable.DataAreaId)
            {
                //Insert CustInvoiceLines in DB;
                custInvoiceLineList.insertDatabase();
            }
            // Attach note
            this.createAttachedNote(custInvoiceTable.RecId,
                custInvoiceTable.TableId,
                strFmtLB(strFmt("@MET:FTIVendorNotes", _cbCTInvoiceHeaderTable.Number, _cbCTInvoiceHeaderTable.CustomerAccount, custTable.name())),
                custInvoiceTable.DataAreaId);
                                              
        }
        catch
        {
            error(this.getInfologMessage());
            throw error("@MET:CustomerFreeTextInvoiceError");
        }

        return custInvoiceTable;
    }

/// <summary>
/// Create attachment notes
/// </summary>
/// <param name = "_refRecId">Source table recid</param>
/// <param name = "_refTableId">Source tableId</param>
/// <param name = "_note">Notes to be attached</param>
/// <param name = "_legalEntity">Company</param>
private void createAttachedNote(RefRecId _refRecId, RefTableId _refTableId, Notes _note, DataAreaId _legalEntity)
{
    DocuRef docuRef;
    changecompany(_legalEntity)
    {
        docuRef.clear();
        docuRef.initValue();
        docuRef.TypeId = 'Note';
        docuRef.RefCompanyId = _legalEntity;
        docuRef.RefRecId = _refRecId;
        docuRef.RefTableId = _refTableId;
        docuRef.Name = "@MET:ALMSupplierVolumetricRebate";
        docuRef.Notes = _note;
        docuRef.Restriction = DocuRestriction::External;
        DocuRef.insert();
    }
}

    /// <summary>
    /// Update FTI invoice id on Charge through header post FTI invoice 
    /// </summary>
    /// <param name = "_InvoiceHeaderTable">CBCTInvoiceHeaderTable</param>
    public void updateFTIInvoiceIdOnCTHeader(METCBCTInvoiceHeaderTable _invoiceHeaderTable)
    {
        //update invoiceid post posting of FTI
        CustInvoiceTable custInvoiceTableLoc;
                    
        select firstonly InvoiceId, Posted from custInvoiceTableLoc
            where custInvoiceTableLoc.RecId == _invoiceHeaderTable.RefFTIRecId;

        if (custInvoiceTableLoc.Posted && custInvoiceTableLoc.InvoiceId)
        {
            ttsbegin;
            _invoiceHeaderTable = METCBCTInvoiceHeaderTable::find(_invoiceHeaderTable.Number, true);
            _invoiceHeaderTable.RefFTIInvoiceId = custInvoiceTableLoc.InvoiceId;
            _invoiceHeaderTable.update();
            ttscommit;
        }
    }

    private str getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;
        str infologMessage;
        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }

        return infologMessage;
    }

    public METInvoiceTypeSO getSOChargeType(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        METInvoiceTypeSO mETInvoiceTypeSO;
        switch (_cbCTInvoiceHeaderTable.InvoiceType)
        {
            case METInvoiceType::ChargeThrough:
                mETInvoiceTypeSO = METInvoiceTypeSO::ChargeThrough;
                break;

            case METInvoiceType::ChargeThroughClaim:
                mETInvoiceTypeSO = METInvoiceTypeSO::ChargeThroughClaim;
                break;

            case METInvoiceType::CrossDock:
                mETInvoiceTypeSO = METInvoiceTypeSO::CrossDock;
                break;

            case METInvoiceType::CrossDockClaim:
                mETInvoiceTypeSO = METInvoiceTypeSO::CrossDockClaim;
                break;

            case METInvoiceType::RDA:
                mETInvoiceTypeSO = METInvoiceTypeSO::RDA;
                break;

            case METInvoiceType::SVR:
                mETInvoiceTypeSO = METInvoiceTypeSO::SVR;
                break;

            default:
                mETInvoiceTypeSO = METInvoiceTypeSO::Blank;
                break;
        }
        return mETInvoiceTypeSO;
    }
